const input = $json;
const raw = input.rawPayload || input;
const data = raw.data || {};
const fields = Array.isArray(data.fields) ? data.fields : (Array.isArray(raw.fields) ? raw.fields : []);
const str = (value) => {
  if (value === null || value === undefined) return '';
  if (Array.isArray(value)) return value.map(str).filter(Boolean).join(', ');
  if (typeof value === 'object') return str(value.text ?? value.label ?? value.value ?? JSON.stringify(value));
  return String(value).trim();
};
const key = (value) => str(value).toLowerCase().replace(/[^a-z0-9]+/g, '');
const mapped = {};
for (const field of fields) {
  const options = Array.isArray(field.options) ? new Map(field.options.map((option) => [str(option.id), str(option.text || option.label || option.value || option.id)])) : new Map();
  const rawAnswer = field.value ?? field.answer;
  const answer = Array.isArray(rawAnswer) && options.size ? rawAnswer.map((value) => options.get(str(value)) || str(value)).filter(Boolean).join(', ') : str(rawAnswer);
  for (const alias of [field.key, field.label, field.title, field.name].filter(Boolean)) {
    mapped[key(alias)] = answer;
  }
}
for (const [alias, value] of Object.entries(input)) {
  if (alias !== 'rawPayload' && alias !== 'paymentNextStep') mapped[key(alias)] = str(value);
}
const pick = (aliases, fallback = 'Not provided') => {
  for (const alias of aliases) {
    const value = mapped[key(alias)];
    if (value) return value;
  }
  return fallback;
};
const packageKey = (value) => {
  const normalized = key(value);
  if (normalized.includes('starter') || normalized === '49') return 'starter';
  if (normalized.includes('pro') || normalized.includes('followup') || normalized === '149') return 'pro';
  if (normalized.includes('custom') || normalized.includes('build') || normalized.includes('booking')) return 'custom';
  return 'unknown';
};
const packageLabels = {
  starter: 'Starter System',
  pro: 'Pro Follow-Up System',
  custom: 'Custom Build'
};
const nextSteps = {
  starter: { type: 'stripe_payment_link', label: 'Starter System', amount: 49, url: process.env.STRIPE_PAYMENT_LINK_STARTER || 'https://buy.stripe.com/...' },
  pro: { type: 'stripe_payment_link', label: 'Pro Follow-Up System', amount: 149, url: process.env.STRIPE_PAYMENT_LINK_PRO || 'https://buy.stripe.com/...' },
  custom: { type: 'booking_link', label: 'Custom Build', url: process.env.CUSTOM_BUILD_BOOKING_LINK || 'https://cal.com/your-booking-link' },
  unknown: { type: 'manual_follow_up', label: 'Manual Follow-Up', url: process.env.CUSTOM_BUILD_BOOKING_LINK || 'https://cal.com/your-booking-link' }
};
const eventType = str(raw.eventType || raw.type || input.eventType || 'FORM_RESPONSE');
const name = pick(['name', 'full name', 'full_name', 'contact name'], 'Unknown Lead');
const email = pick(['email', 'email address', 'contact email'], '').toLowerCase();
const business = pick(['business', 'company', 'business name', 'company name']);
const rawPackage = pick(['package', 'select package', 'selected package', 'plan', 'offer']);
const selectedPackageKey = packageKey(rawPackage);
const selectedPackage = packageLabels[selectedPackageKey] || rawPackage;
const budget = pick(['budget', 'monthly budget', 'project budget', 'estimated budget']);
const need = pick(['need', 'primary need', 'what do you need', 'use case', 'project need']);
const source = pick(['source', 'utm_source', 'utm source', 'referral source', 'form', 'form name'], str(data.formName) || 'Tally');
const receivedAt = str(input.receivedAt) || new Date().toISOString();
const leadId = str(input.leadId) || `lead_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`;
const paymentStatus = str(input.paymentStatus) || 'Pending';
const leadStatus = str(input.leadStatus || input.status) || 'New Lead';
const nextStep = input.paymentNextStep || nextSteps[selectedPackageKey] || nextSteps.unknown;
if (eventType !== 'FORM_RESPONSE') {
  return [{ json: { accepted: false, reason: 'Ignored non-FORM_RESPONSE Tally event', eventType, receivedAt, rawPreview: JSON.stringify(raw).slice(0, 1200) } }];
}
return [{
  json: {
    accepted: true,
    leadId,
    name,
    email,
    business,
    package: selectedPackage,
    budget,
    need,
    source,
    leadStatus,
    status: leadStatus,
    paymentStatus,
    paymentNextStepType: nextStep.type,
    paymentNextStepLabel: nextStep.label,
    paymentNextStepUrl: nextStep.url || '',
    paymentAmount: nextStep.amount || '',
    receivedAt,
    formId: str(data.formId || raw.formId || input.formId),
    responseId: str(data.responseId || raw.responseId || input.responseId),
    emailExists: Boolean(email),
    rawPreview: JSON.stringify(raw).slice(0, 1200)
  }
}];

